using Utsav.Domain.Authentication;

namespace Utsav.UnitTests.Authentication;

/// <summary>
/// Expected hashes generated by running the REAL server/auth.mjs algorithm
/// under Node (crypto.scryptSync), with fixed salts so the output is
/// reproducible — not read off the source and hand-translated. Node:
///
///   const { scryptSync } = require("node:crypto");
///   scryptSync("password123", "0102030405060708090a0b0c0d0e0f10", 64).toString("hex")
///
/// A change to ScryptPasswordHasher that still passes these has not drifted
/// from Node's actual behaviour.
/// </summary>
public class ScryptPasswordHasherTests
{
    [Theory]
    [InlineData("password123", "0102030405060708090a0b0c0d0e0f10",
        "e1e2d47840bacf446239abc6a88936d8cd9dcf0c9a6c666c4894214be367b08f6f9b42ea470472578fd96137e4e4174ea97d9938cc00e8a535f702b9f7032c52")]
    [InlineData("S3cure!Pass_Word", "aabbccddeeff00112233445566778899",
        "95405cd6f2b8db71f8c2f8f4204ab9d771106a78021c2dbacbdc13ad2d22a82dd4058df7e9ef1a8c9bc87df1cadc03295121627861588faa97d63aab7eee99b2")]
    [InlineData("", "0000000000000000000000000000000",
        "d9f797976826e6920f6669a7bd9b3d539e0688374ce4a165f7d85537bd7c6283183cc5e51b9aa41fdb18a5b2f8fa16a78ae67a9f7160104d82e2dac8bdd51582")]
    public void Verify_accepts_a_hash_produced_by_the_real_Node_algorithm(string password, string saltHex, string expectedHashHex)
    {
        var stored = $"{saltHex}:{expectedHashHex}";
        Assert.True(ScryptPasswordHasher.Verify(password, stored));
    }

    [Fact]
    public void Verify_rejects_the_wrong_password()
    {
        var stored = ScryptPasswordHasher.Hash("correct-horse-battery-staple");
        Assert.False(ScryptPasswordHasher.Verify("wrong-password", stored));
    }

    [Fact]
    public void Hash_output_round_trips_through_Verify()
    {
        var stored = ScryptPasswordHasher.Hash("some-password-42");
        Assert.True(ScryptPasswordHasher.Verify("some-password-42", stored));
    }

    [Fact]
    public void Hash_salts_each_call_differently()
    {
        var first = ScryptPasswordHasher.Hash("same-password");
        var second = ScryptPasswordHasher.Hash("same-password");
        Assert.NotEqual(first, second);
    }

    /// <summary>Google-provisioned users have no local password (auth.mjs verifyPassword).</summary>
    [Theory]
    [InlineData(null)]
    [InlineData("")]
    public void Verify_rejects_a_null_or_empty_stored_hash(string? stored) =>
        Assert.False(ScryptPasswordHasher.Verify("anything", stored));

    [Fact]
    public void Verify_rejects_a_malformed_stored_value_instead_of_throwing() =>
        Assert.False(ScryptPasswordHasher.Verify("anything", "not-the-expected-format"));
}
